import "./auth/localTestSecrets.ts";
import * as Cloudflare from "@alchemy.run/cloudflare";
import * as Test from "@alchemy.run/test/Vitest";
import * as Alchemy from "alchemy";
import { assert } from "@effect/vitest";
import * as Effect from "effect/Effect";
import MainWorker from "./MainWorker.ts";
import SubmissionWorker from "./SubmissionWorker.ts";

const { test, beforeAll, deploy } = Test.make({
  providers: Cloudflare.providers(),
  dev: true,
});

const Stack = Alchemy.Stack(
  "SurveybeatSubmissionExchangeTest",
  { providers: Cloudflare.providers(), state: Alchemy.localState() },
  Effect.gen(function* () {
    const main = yield* MainWorker;
    const submission = yield* SubmissionWorker;
    return { main: main.url.as<string>(), submission: submission.url.as<string>() };
  }),
);

const stack = beforeAll(deploy(Stack), { timeout: 240_000 });

const tokenFrom = (text: string): string => /#t=([A-Za-z0-9_-]+)/.exec(text)?.[1] ?? "";

test(
  "the Submission Worker exchanges a test Invitation's token for its context, with CORS headers",
  Effect.gen(function* () {
    const { main, submission } = yield* stack;
    const run = crypto.randomUUID();
    const seeded = yield* Effect.promise(() => fetch(`${main}/__test/test-invitations?run=${run}`));
    assert.strictEqual(seeded.status, 200);

    const captured = yield* Effect.promise(() =>
      fetch(`${main}/__test/email?recipient=${encodeURIComponent("admin@example.com")}`),
    );
    const { text } = (yield* Effect.promise(() => captured.json())) as { text: string | null };
    const token = tokenFrom(text ?? "");
    assert.isAbove(token.length, 0, "the captured test Invitation carries a token");

    const exchanged = yield* Effect.promise(() =>
      fetch(`${submission}/exchange`, {
        method: "POST",
        headers: { "content-type": "application/json", origin: "https://dashboard.surveybeat.app" },
        body: JSON.stringify({ token }),
      }),
    );
    assert.strictEqual(exchanged.status, 200);
    assert.strictEqual(exchanged.headers.get("access-control-allow-origin"), "*");
    const context = (yield* Effect.promise(() => exchanged.json())) as { test?: boolean; questions: Array<unknown> };
    assert.strictEqual(context.test, true);
    assert.isAbove(context.questions.length, 0);
  }),
);

